Set-StrictMode -Version Latest
$ErrorActionPreference = "Stop"
$env:GIT_PAGER = "cat"
$env:NPM_CONFIG_LOGLEVEL = "error"

$Root = (Get-Location).Path
$RelativePath = "app/page.tsx"
$Target = Join-Path $Root $RelativePath
$BackupDirectory = Join-Path $Root ".orcaly-backups"
$Timestamp = Get-Date -Format "yyyyMMdd-HHmmss"
$Backup = Join-Path $BackupDirectory "home-page-$Timestamp.tsx"
$PageBase64 = @'

'@

function Write-Section([string]$Text) {
    Write-Host ""
    Write-Host ("=" * 68) -ForegroundColor DarkCyan
    Write-Host $Text -ForegroundColor Cyan
    Write-Host ("=" * 68) -ForegroundColor DarkCyan
}

function Restore-Home {
    if (Test-Path -LiteralPath $Backup) {
        Write-Host "[AVISO] Restaurando a Home anterior..." -ForegroundColor Yellow
        Copy-Item -LiteralPath $Backup -Destination $Target -Force
    }
}

Write-Section "ORCALY - NOVA HOME RESPONSIVA E COMERCIAL"

if (-not (Test-Path -LiteralPath (Join-Path $Root "package.json"))) {
    throw "Execute este script na raiz do projeto Orçaly."
}

git rev-parse --is-inside-work-tree | Out-Null

if ($LASTEXITCODE -ne 0) {
    throw "A pasta atual não é um repositório Git."
}

if (-not (Test-Path -LiteralPath $Target)) {
    throw "Arquivo não encontrado: $RelativePath"
}

New-Item -ItemType Directory -Path $BackupDirectory -Force | Out-Null
Copy-Item -LiteralPath $Target -Destination $Backup -Force

Write-Host "[OK] Backup: $Backup" -ForegroundColor Green

try {
    Write-Section "APLICANDO A NOVA HOME"

    $Bytes = [Convert]::FromBase64String(
        ($PageBase64 -replace "\s", "")
    )

    [System.IO.File]::WriteAllBytes($Target, $Bytes)

    $Content = [System.IO.File]::ReadAllText(
        $Target,
        [System.Text.Encoding]::UTF8
    )

    $RequiredTexts = @(
        "ORCALY_HOME_CONVERSION_V2",
        "Organize sua empresa e transforme cada contato",
        "Soluções por segmento",
        "Planos transparentes",
        "Plano Básico",
        "Plano Intermediário",
        "Plano Premium",
        "49.9",
        "99.9",
        "149.9",
        "Comparação de recursos",
        "Fale conosco",
        "orcalybr@gmail.com",
        "mobile-navigation",
        "Comparar planos"
    )

    foreach ($Text in $RequiredTexts) {
        if (-not $Content.Contains($Text)) {
            throw "Conteúdo obrigatório não encontrado: $Text"
        }

        Write-Host "[OK] $Text" -ForegroundColor Green
    }

    $CorruptedPatterns = @(
        "OrÃ",
        "organizaÃ",
        "soluÃ",
        "negÃ",
        "âœ",
        "ðŸ"
    )

    foreach ($Pattern in $CorruptedPatterns) {
        if ($Content.Contains($Pattern)) {
            throw "Texto corrompido encontrado: $Pattern"
        }
    }

    Write-Host "[OK] Codificação UTF-8 validada." -ForegroundColor Green

    Write-Section "VERIFICANDO O DIFF"

    git --no-pager diff --check -- $RelativePath

    if ($LASTEXITCODE -ne 0) {
        throw "git diff --check encontrou problemas."
    }

    $Package = Get-Content `
        -LiteralPath (Join-Path $Root "package.json") `
        -Raw |
        ConvertFrom-Json

    if ($Package.scripts.PSObject.Properties.Name -contains "security:check") {
        Write-Section "VALIDANDO SEGURANÇA"

        npm run security:check

        if ($LASTEXITCODE -ne 0) {
            throw "security:check falhou."
        }

        Write-Host "[OK] SECURITY_CHECK_EXIT_CODE=0" -ForegroundColor Green
    }

    Remove-Item `
        -LiteralPath (Join-Path $Root ".next") `
        -Recurse `
        -Force `
        -ErrorAction SilentlyContinue

    Write-Section "EXECUTANDO BUILD COMPLETO"

    npm run build
    $BuildExitCode = $LASTEXITCODE

    Write-Host ""
    Write-Host "BUILD_EXIT_CODE=$BuildExitCode" -ForegroundColor Yellow

    if ($BuildExitCode -ne 0) {
        throw "O build falhou."
    }

    Write-Section "NOVA HOME APLICADA COM SUCESSO"

    Write-Host "Arquivo: $RelativePath"
    Write-Host "Backup: $Backup"
    Write-Host "Build: aprovado"
    Write-Host "Commit: não realizado"
    Write-Host "Deploy: não realizado"
    Write-Host ""
    Write-Host "Principais melhorias:" -ForegroundColor Cyan
    Write-Host "  - menu móvel completo"
    Write-Host "  - hero reorganizado e responsivo"
    Write-Host "  - soluções por segmento preservadas"
    Write-Host "  - comparação dos três planos"
    Write-Host "  - contato: orcalybr@gmail.com"
    Write-Host "  - FAQ e CTAs distribuídos"
    Write-Host "  - barra de ação fixa no celular"
}
catch {
    Restore-Home
    throw
}
